// Octonion Cayley-Dickson Test Suite
//
// Self-contained tests validating:
//   1. Octonion multiplication (norm-multiplicativity: |o1*o2| = |o1|*|o2|)
//   2. Conjugate properties
//   3. Inverse: o * o^{-1} = identity
//   4. Cayley-Dickson decomposition round-trip
//   5. Non-associativity: (e1*e2)*e4 != e1*(e2*e4)
//   6. Alternative law: (o*o)*x = o*(o*x)
//   7. Identity element
//
// All functions inlined (tests cannot import stdlib).
//
// Reference: Baez, "The Octonions", Bull. AMS 2002

// ============================================================================
// MATH HELPERS
// ============================================================================

fn abs_f32(x: f32) -> f32 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_f32(x: f32) -> f32 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var g = x / 2.0
    if g < 1.0 { g = 1.0 }
    var i = 0
    while i < 60 {
        g = (g + x / g) / 2.0
        i = i + 1
    }
    return g
}

fn approx_eq_f32(a: f32, b: f32, tol: f32) -> bool with Mut, Panic, Div {
    abs_f32(a - b) < tol
}

// ============================================================================
// OCTONION STRUCT AND CORE OPERATIONS (inlined from stdlib/math/octonion.sio)
// ============================================================================

struct Oct {
    a: f32, b: f32, c: f32, d: f32,
    e: f32, f: f32, g: f32, h: f32,
}

fn oct(a: f32, b: f32, c: f32, d: f32, e: f32, f: f32, g: f32, h: f32) -> Oct {
    Oct { a: a, b: b, c: c, d: d, e: e, f: f, g: g, h: h }
}

fn oct_norm_sq(o: Oct) -> f32 {
    o.a * o.a + o.b * o.b + o.c * o.c + o.d * o.d +
    o.e * o.e + o.f * o.f + o.g * o.g + o.h * o.h
}

fn oct_norm(o: Oct) -> f32 with Mut, Panic, Div {
    sqrt_f32(oct_norm_sq(o))
}

fn oct_conj(o: Oct) -> Oct {
    Oct { a: o.a, b: 0.0-o.b, c: 0.0-o.c, d: 0.0-o.d,
          e: 0.0-o.e, f: 0.0-o.f, g: 0.0-o.g, h: 0.0-o.h }
}

// Cayley-Dickson multiplication: standard basis {1,i,j,k,l,il,jl,kl}
// Non-associative, 64 muls + 56 adds (Baez 2002)
fn oct_mul(a: Oct, b: Oct) -> Oct {
    let c0 = a.a*b.a - a.b*b.b - a.c*b.c - a.d*b.d - a.e*b.e - a.f*b.f - a.g*b.g - a.h*b.h
    let c1 = a.a*b.b + a.b*b.a + a.c*b.d - a.d*b.c + a.e*b.f - a.f*b.e - a.g*b.h + a.h*b.g
    let c2 = a.a*b.c - a.b*b.d + a.c*b.a + a.d*b.b + a.e*b.g + a.f*b.h - a.g*b.e - a.h*b.f
    let c3 = a.a*b.d + a.b*b.c - a.c*b.b + a.d*b.a + a.e*b.h - a.f*b.g + a.g*b.f - a.h*b.e
    let c4 = a.a*b.e - a.b*b.f - a.c*b.g - a.d*b.h + a.e*b.a + a.f*b.b + a.g*b.c + a.h*b.d
    let c5 = a.a*b.f + a.b*b.e - a.c*b.h + a.d*b.g - a.e*b.b + a.f*b.a - a.g*b.d + a.h*b.c
    let c6 = a.a*b.g + a.b*b.h + a.c*b.e - a.d*b.f - a.e*b.c + a.f*b.d + a.g*b.a - a.h*b.b
    let c7 = a.a*b.h - a.b*b.g + a.c*b.f + a.d*b.e - a.e*b.d - a.f*b.c + a.g*b.b + a.h*b.a
    Oct { a: c0, b: c1, c: c2, d: c3, e: c4, f: c5, g: c6, h: c7 }
}

fn oct_inv(o: Oct) -> Oct with Mut, Panic, Div {
    let ns = oct_norm_sq(o)
    let c = oct_conj(o)
    Oct { a: c.a/ns, b: c.b/ns, c: c.c/ns, d: c.d/ns,
          e: c.e/ns, f: c.f/ns, g: c.g/ns, h: c.h/ns }
}

// ============================================================================
// CAYLEY-DICKSON DECOMPOSITION (inlined from stdlib)
// ============================================================================

struct OctonionParts {
    q0_a: f32, q0_b: f32, q0_c: f32, q0_d: f32,
    q1_a: f32, q1_b: f32, q1_c: f32, q1_d: f32,
}

fn oct_to_parts(o: Oct) -> OctonionParts {
    OctonionParts {
        q0_a: o.a, q0_b: o.b, q0_c: o.c, q0_d: o.d,
        q1_a: o.e, q1_b: o.f, q1_c: o.g, q1_d: o.h,
    }
}

fn oct_from_parts(p: OctonionParts) -> Oct {
    Oct { a: p.q0_a, b: p.q0_b, c: p.q0_c, d: p.q0_d,
          e: p.q1_a, f: p.q1_b, g: p.q1_c, h: p.q1_d }
}

