// Test 5: (A^T)^T = A identity for transpose
fn test_sparse_transpose() -> bool with IO, Mut, Panic, Div {
    // Build a non-symmetric 3x3 matrix via triplets
    var rows: [i32; 1024] = [0; 1024]
    var cols: [i32; 1024] = [0; 1024]
    var vals: [f64; 1024] = [0.0; 1024]

