    // L = [[2, 0, 0],
    //      [1, 3, 0],
    //      [4, 5, 6]]
    // Build via triplets
    var rows: [i32; 1024] = [0; 1024]
    var cols: [i32; 1024] = [0; 1024]
    var vals: [f64; 1024] = [0.0; 1024]

    rows[0] = 0; cols[0] = 0; vals[0] = 2.0
    rows[1] = 1; cols[1] = 0; vals[1] = 1.0
    rows[2] = 1; cols[2] = 1; vals[2] = 3.0
    rows[3] = 2; cols[3] = 0; vals[3] = 4.0
    rows[4] = 2; cols[4] = 1; vals[4] = 5.0
    rows[5] = 2; cols[5] = 2; vals[5] = 6.0

    let l = sparse_from_triplets(rows, cols, vals, 6, 3, 3)

    // b = [2, 7, 45]
    // Exact solution: x[0] = 1, x[1] = 2, x[2] = 3
    // Forward sub: x[0] = 2/2 = 1
    //              x[1] = (7 - 1*1)/3 = 6/3 = 2
    //              x[2] = (45 - 4*1 - 5*2)/6 = (45-4-10)/6 = 31/6
    // Let's compute exact b for x = [1, 2, 3]:
    // b[0] = 2*1 = 2
    // b[1] = 1*1 + 3*2 = 7
    // b[2] = 4*1 + 5*2 + 6*3 = 4+10+18 = 32
    var b: [f64; 128] = [0.0; 128]
    b[0] = 2.0
    b[1] = 7.0
    b[2] = 32.0

    let x = sparse_lower_solve(l, b, 3)

    let e0 = abs_f64(x[0] - 1.0)
    let e1 = abs_f64(x[1] - 2.0)
    let e2 = abs_f64(x[2] - 3.0)

    print("  x=[")
    print(x[0])
    print(", ")
    print(x[1])
    print(", ")
    print(x[2])
    println("]")

    return e0 < 1e-10 && e1 < 1e-10 && e2 < 1e-10
}

