    rows[4] = 1; cols[4] = 2; vals[4] = 5.0
    rows[5] = 2; cols[5] = 2; vals[5] = 6.0

    let u = sparse_from_triplets(rows, cols, vals, 6, 3, 3)

    // For x = [1, 2, 3]:
    // b[0] = 2*1 + 1*2 + 4*3 = 2+2+12 = 16
    // b[1] = 3*2 + 5*3 = 6+15 = 21
    // b[2] = 6*3 = 18
    var b: [f64; 128] = [0.0; 128]
    b[0] = 16.0
    b[1] = 21.0
    b[2] = 18.0

    let x = sparse_upper_solve(u, b, 3)

    let e0 = abs_f64(x[0] - 1.0)
    let e1 = abs_f64(x[1] - 2.0)
    let e2 = abs_f64(x[2] - 3.0)

